        { k = "objective", t = "Use Hillsbrad Proclamation", q = 532, o = 3, ic = "use", n = "Hillsbrad Proclamation", e = "object", id = 1761, m = 1424, x = 29.73, y = 41.75, lvl = 30 },
        { k = "objective", t = "Hillsbrad Town Registry", q = 532, o = 4, ic = "pickup", n = "Hillsbrad Town Registry", e = "item", id = 3657, c = 1, m = 1424, x = 29.52, y = 41.53, nt = { { l = 1, t = "Loot them from Hillsbrad Town Registry." }, { l = 2, t = "The town hall is the big house in the west of Hillsbrad Fields. Magistrate Burnside stands in its large room with the Proclamation in front of him and the Registry (a book) in the corner; the Councilmen are in and around the house. The rooms are packed, with casters that shoot through doorways: pull carefully and expect two or three at once. The Registry respawns within a minute, so both of you get one." } }, lvl = 30 },
        { k = "turnin", t = "Turn in Helcular's Revenge to Helcular's Grave", q = 553, ic = "object", n = "Helcular's Grave", e = "object", id = 1767, m = 1424, x = 52.75, y = 53.37, nt = { { l = 2, t = "Helcular's grave is the easternmost one of the Southshore graveyard, next to the river. The elite Southshore guards see through stealth and daze you. Stay away from the town: come up from the river on the east side and slip between the two trees just before the graveyard, click the grave and leave the same way. A Lesser Invisibility Potion helps; if a guard catches you, die near the grave, run back as a ghost, resurrect beside it and click it at once." } }, lvl = 30, wp = { -486, 122, -513, 104, -504, 96, -504, 71, -738, -171 } },
