        { k = "objective", t = "Corrupt Manifestation's Bracers", q = 63, o = 1, ic = "get", n = "Corrupt Manifestation's Bracers", e = "item", id = 7812, c = 1, m = 1421, x = 38.78, y = 44.26, mobs = { "Corrupt Minor Manifestation of Water" }, mi = { 5894 }, nt = { { l = 2, t = "Stand next to the standing stone and drink the Water Sapta: water elementals appear around the pool. Only one can be attacked, the corrupt one near the middle (level 22): kill it for the bracers. If someone killed it just before you, it is back within about 5 minutes. Something went wrong? Tiev Mordune, sitting behind the stone, helps those who bring him another Sapta." } }, lvl = 30, only = { 4, 15, 21, 27 }, wp = { 513, 1694, 513, 1504, 604, 1413, 671, 1413, 754, 1496, 754, 1554, 813, 1621, 813, 1738, 804, 1754, 704, 1863, 679, 1863, 629, 1896, 513, 1896, 479, 1888, 429, 1838 } },
