        { k = "objective", t = "Kill Foreman Bonds", q = 539, o = 1, ic = "kill", n = "Foreman Bonds", e = "npc", id = 2305, m = 1424, x = 31.21, y = 56.01, mobs = { "Foreman Bonds" }, mi = { 2305 }, lvl = 30, wp = { 0, -860, -329, -538, -371, -538, -371, -529, -529, -371, -529, -263, -538, -263, -796, -4 }, wv = { { { 4, 15, 21, 27 }, {} } } },
        { k = "objective", t = "Kill Hillsbrad Miner x10", q = 539, o = 2, ic = "kill", n = "Hillsbrad Miner", e = "npc", id = 2269, m = 1424, x = 29.78, y = 56.11, spots = { { m = 1424, x = 30.45, y = 51.86 } }, mobs = { "Hillsbrad Miner" }, mi = { 2269 }, nt = { { l = 2, t = "Azurelode Mine is just south of Hillsbrad Fields; the sentries outside call each other for help, the miners inside come one at a time (they run when hurt). Foreman Bonds stands on a raised platform deep inside (the entrance is on its south-west side; take the lower way in, then the first fork right). Below 20% he calls two dwarves: burst him down, or stun him as he gets low." } }, lvl = 30 },
        { k = "objective", t = "Kill Miner Hackett", q = 567, o = 3, ic = "kill", n = "Miner Hackett", e = "npc", id = 2450, m = 1424, x = 30.3, y = 57.5, mobs = { "Miner Hackett" }, mi = { 2450 }, nt = { { l = 2, t = "Miner Hackett is in the north-east nook of the mine, where you can jump down to a lower level." } }, lvl = 30 },
        { k = "objective", t = "Hillsbrad Human Skull x30", q = 546, o = 1, ic = "get", n = "Hillsbrad Human Skull", e = "item", id = 3692, c = 30, m = 1424, x = 29.8, y = 55.5, spots = { { m = 1424, x = 30.45, y = 51.86 } }, mobs = { "Hillsbrad Miner", "Hillsbrad Foreman", "Hillsbrad Sentry", "Hillsbrad Farmer", "Hillsbrad Peasant" }, mi = { 2269, 2503, 2270, 2266, 2267 }, nt = { { l = 2, t = "Still short of skulls? The miners seem to drop them more often; the Syndicate mages of Durnholde Keep, south-east of Tarren Mill across the river, are another good source. Or right-click to skip Souvenirs of Death." } }, lvl = 30 },
